/// Returns true if and only if `s` contains `val`.
fn slice_contains(s: &[i32], val: i32) -> bool {
    for &x in s {
        if x == val {
            return true;
        }
    }
    false
}

/// Returns true if and only if the two slices `a` and `b` share at least one common element.
fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    for &x in a {
        if slice_contains(b, x) {
            return true;
        }
    }
    false
}

