        let empty: &[i32] = &[];
        assert!(!slice_contains(empty, 5));
        let arr = &[1, 2, 3, 4, 5];
        assert!(slice_contains(arr, 1));
        assert!(slice_contains(arr, 5));
        assert!(!slice_contains(arr, 0));
        assert!(!slice_contains(arr, 6));
